-- Operating rules, one row per problem type. Kept in their own file so they
-- can be re-applied to an existing database (npm run reset does this).
-- Waiting times are Team Demo Rules and run on the simulated clock.
DELETE FROM procedures;
INSERT INTO procedures VALUES
('MISSING_INVOICE', 'Missing invoice', 'shipper', 'broker', 'shipper,broker',
 'The commercial invoice (PDF) showing the AWB number, consignee, items, quantities, values and currency. Send it to the broker with operations copied.',
 2, 4, 6,
 'Broker says the invoice was accepted; the invoice shows this AWB, consignee and goods; the clearance reference is found in the customs record showing RELEASED, dated after our request.',
 'Invoice sent by the shipper; a screenshot of an email; a copy of the invoice without broker acceptance; received but not accepted; a clearance reference not found in the customs record.',
 true),
('INVOICE_REF_MISMATCH', 'Wrong shipment reference on the invoice', 'shipper', 'broker', 'shipper,broker',
 'A corrected commercial invoice with the exact AWB number, consignee and goods, a new version number, and a note saying which earlier version it replaces.',
 2, 4, 6,
 'The corrected invoice shows this AWB, consignee and goods; it is a newer version naming the old one as replaced; the broker accepted it; the release reference is found in the customs record.',
 'A promise of a new invoice; an invoice still showing another AWB or consignee; the same invoice again with no new version; a corrected invoice without broker confirmation.',
 true),
('TRANSPORT_DELAY', 'Transport delay or cargo moved to a later departure', 'carrier', 'carrier', 'carrier',
 'Where the cargo is now, rebooking status, the new flight and departure time, the revised arrival estimate and the movement record.',
 3, 6, 10,
 'Two stages: carrier movement record shows actual departure (case becomes Awaiting arrival), then a reliable tracking update shows ARRIVED at the destination.',
 'A new booking or reschedule notice; we are checking with the station; an estimated arrival time; a departed status on its own; a flight number with no movement record.',
 false),
('CONFLICTING_STATUS', 'Conflicting shipment status', 'broker', 'consignee', 'broker,consignee',
 'Cleared claims: timestamped customs status, release reference and reason for the difference. Delivered claims: proof of delivery or signed receipt.',
 2, 4, 6,
 'The customs record shows RELEASED later than the hold with a matching release reference; the broker explains the difference; if delivery is claimed, a signed receipt from the consignee; the old claim stays in history.',
 'A verbal or informal statement; second-hand claims such as the carrier says it is released; a carrier available or delivered status while customs still shows a hold; a record older than the hold.',
 true),
('HS_CODE_ERROR', 'Wrong product code or HS code', 'shipper', 'broker', 'shipper,broker',
 'Product specification sheets, material details and intended use. The revised invoice is requested after the broker has reviewed the code. Agents never suggest or approve a code.',
 2, 4, 6,
 'Specifications support the goods description; the broker review record shows the approved code; the corrected invoice is a new version carrying that code; the broker confirms customs accepted the amended entry and the release reference is in the customs record.',
 'An email saying we changed the code; an edited invoice the broker has not reviewed; anyone''s opinion on the code; specification sheets with no broker review.',
 true),
('WEIGHT_MISMATCH', 'Weight mismatch', 'shipper', 'broker', 'shipper,carrier,warehouse,broker',
 'A corrected packing list or a dated re-weigh record with the piece count, saying whether the weight is gross, net or chargeable. The carrier is copied for its acceptance weight record.',
 2, 4, 6,
 'A dated official weight record (the carrier''s acceptance weight or a re-weigh) with the same weight type, units and piece count; the corrected document now matches the record; the broker accepted the correction and the release reference is in the customs record.',
 'It was just a typo; probably the packaging, use the AWB weight; an estimate or undated record; comparing gross with chargeable weight; a record for a different shipment.',
 true),
('MISSING_CERTIFICATE', 'Missing certificate', 'shipper', 'broker', 'shipper,broker',
 'The official signed and stamped certificate (PDF) matching the AWB, invoice, consignee and goods. If pending, the issuer name, application reference and expected issue time.',
 3, 6, 8,
 'The issued certificate (not an application) with issuer, signature or stamp and date, matching the AWB, invoice, consignee and goods; the broker accepted it and the release reference is in the customs record.',
 'An application receipt; it is in process; an unsigned draft or a certificate for another shipment; a certificate with no broker confirmation.',
 true);
